Here's a thread-safe Service Locator with lazy initialization:

```rust
use std::collections::HashMap;
use std::any::{Any, TypeId};
use std::sync::{Arc, Mutex, Once};
use std::marker::PhantomData;

type ServiceFactory = Box<dyn Fn() -> Box<dyn Any + Send + Sync> + Send + Sync>;

pub struct ServiceLocator {
    services: Arc<Mutex<HashMap<TypeId, Box<dyn Any + Send + Sync>>>>,
    factories: Arc<Mutex<HashMap<TypeId, ServiceFactory>>>,
}

impl ServiceLocator {
    pub fn new() -> Self {
        Self {
            services: Arc::new(Mutex::new(HashMap::new())),
            factories: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn register_factory<T, F>(&self, factory: F)
    where
        T: 'static + Send + Sync,
        F: Fn() -> T + 'static + Send + Sync,
    {
        let type_id = TypeId::of::<T>();
        let boxed_factory = Box::new(move || Box::new(factory()) as Box<dyn Any + Send + Sync>);
        self.factories.lock().unwrap().insert(type_id, boxed_factory);
    }

    pub fn get<T: 'static + Clone>(&self) -> Option<T> {
        let type_id = TypeId::of::<T>();

        // Check if service already exists
        if let Some(service) = self.services.lock().unwrap().get(&type_id) {
            return service.downcast_ref::<T>().cloned();
        }

        // Create service using factory if available
        if let Some(factory) = self.factories.lock().unwrap().get(&type_id) {
            let service = factory();
            self.services.lock().unwrap().insert(type_id, service);
            return self.services.lock().unwrap().get(&type_id)?.downcast_ref::<T>().cloned();
        }

        None
    }
}
```

This implementation provides thread-safety through Mutex and supports lazy initialization via factory functions.

