Implement Deref and DerefMut traits to automatically access the wrapped struct's methods:

```rust
use std::ops::{Deref, DerefMut};

struct User {
    name: String,
    email: String,
}

struct TrackedUser {
    user: User,
    login_count: u32,
}

impl Deref for TrackedUser {
    type Target = User;

    fn deref(&self) -> &Self::Target {
        &self.user
    }
}

impl DerefMut for TrackedUser {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.user
    }
}

// Now you can call User methods directly on TrackedUser
let mut tracked = TrackedUser { user: User { name: 'John'.to_string(), email: 'john@example.com'.to_string() }, login_count: 0 };
tracked.name = 'Jane'.to_string(); // Works due to DerefMut
